-- Batch 1 cohort slideshows (venn-site #185). Additive: fills cohorts.slides only where it is still null. Source: src/data/batch1-slides.ts.
update public.cohorts set slides = '[{"title":"Your four weeks","body":"In week 1 you take a short course and watch a video from an AWS engineer, in weeks 2 and 3 you build, and in week 4 you show what you made, with Venn pacing each step and telling you what comes next."},{"title":"What AWS cares about","body":"AWS puts much of its public community work behind helping people go from learning to a real job, through free cloud and AI courses, skills training for students and career changers, and education programs with schools and nonprofits."},{"title":"What you will do","body":"With Venn you will come up with one event or build for your org that fits those values, and you will ship one small agent that your org actually uses, the kind your members would miss if it were gone."},{"title":"Why it matters","body":"We cannot guarantee you anything from AWS, and we will not pretend otherwise. What we can say is that an org that has already run something in line with its values is more likely to win that company''s support later."},{"title":"How Venn backs you","body":"Venn will vouch that your work was part of a Venn cohort, and at the end Venn will refer the top 10% of the cohort to AWS, chosen on the quality of your engagement and the impact of what you did."},{"title":"The rule you must follow","body":"This is an AWS-aligned cohort run by Venn, and it is not sponsored by AWS. You can write AWS in words, but never use the AWS logo or any AWS branding in anything you make or share."},{"title":"Who to talk to","body":"All communication goes through contact@joinvenn.org, so write there with any question, idea or problem and Venn will answer or pass it along. Please do not contact the company yourself."}]'::jsonb where slug = 'aws' and slides is null;
update public.cohorts set slides = '[{"title":"Your four weeks","body":"In week 1 you watch a kickoff video, every week after that you have a check-in, and in week 4 you wrap up with a short look back at what you did, with Venn pacing each step."},{"title":"What Quadron looks for","body":"Quadron wants orgs whose members think in public, the builders, researchers and founders who share how they reason as they go and not only what they finished."},{"title":"What you will do","body":"You will work directly with the Quadron team over the four weeks, which means talking with them, showing how your org thinks, and trying what they are building, with Venn keeping it organized."},{"title":"Why it matters","body":"We cannot guarantee you anything from Quadron, and we will not pretend otherwise. What we can say is that an org that has already run something aligned with what a company is building is more likely to win that company''s support later."},{"title":"How Venn backs you","body":"Venn will vouch that your work was part of a Venn cohort, and at the end Venn will refer the top 10% of the cohort to Quadron, chosen on the quality of your engagement and the impact of what you did."},{"title":"The rule you must follow","body":"This is a Quadron-aligned cohort run by Venn, and it is not sponsored by Quadron. You can write Quadron in words, but never use the Quadron logo or any Quadron branding in anything you make or share."},{"title":"Who to talk to","body":"All communication goes through contact@joinvenn.org, so write there with any question, idea or problem and Venn will answer or pass it along. Please do not contact the company yourself."}]'::jsonb where slug = 'quadron' and slides is null;
